import test from 'node:test';
import assert from 'node:assert/strict';
import { tariff2026, taxEffect, donationCheck, childcareCheck, insuranceCheck, indianResidency, transferQuote, taxRecordsCSV, adviserText, recordsForYear } from '../tax-rules.js';
import { employeeHealthAnnual, taxClassSocial2026, doubleHouseholdCandidate, investmentProjection } from '../financial-core.js';
import { calculateExpenseCore } from '../expense-rules.js';
import { opportunityResults, taxPlanningPage } from '../tax-planning.js';

// Fixed reference values, not generated by the JS implementation under test.
// €50,000 single/joint and €49,230 single were independently confirmed in the
// Bavarian tax authority's public calculator on 13 November 2026.
// Boundaries were worked separately using Decimal from the published §32a formula.
const tariffCases = [[0,0,0],[12348,0,0],[12349,0,0],[17799,1034,0],[17800,1035,0],[20000,1570,0],[30000,4217,870],[40000,7209,3140],[49230,10278,5498],[50000,10548,5700],[60000,14233,8434],[69878,18213,11302],[69879,18213,11302],[70000,18264,11340],[277825,105550,94414],[277826,105551,94414]];
for (const [income, single, joint] of tariffCases) test('2026 statutory tariff reference at ' + income, () => {
  assert.equal(tariff2026(income),single); assert.equal(tariff2026(income,true),joint);
});
test('tariff rejects invalid amounts and truncates annual income to whole euros', () => {
  assert.equal(tariff2026(50000.99),10548);
  for (const value of [-1,NaN,Infinity,'',null]) assert.throws(()=>tariff2026(value));
});
const effect = {year:2026,complex:'no',verified:'yes',kind:'employment',assessment:'single',income:50000,spending:2000,candidate:2000,reimbursements:0};
test('employee allowance is not counted as an additional saving: independent €270 example', () => {
  const result=taxEffect(effect);
  assert.equal(result.incrementalDeduction,770);assert.equal(result.before,10548);assert.equal(result.after,10278);assert.equal(result.effect,270);
  assert.equal(taxEffect({...effect,candidate:1000}).effect,0);
  assert.equal(taxEffect({...effect,candidate:1230}).incrementalDeduction,0);
  assert.equal(taxEffect({...effect,reimbursements:770}).effect,0);
});
test('unsupported or unconfirmed assessment cases never produce an effect amount', () => {
  for(const change of [{complex:'yes'},{complex:''},{complex:undefined},{verified:'no'},{verified:''},{assessment:'joint'}]) {
    const result=taxEffect({...effect,...change});assert.equal(result.supported,false);assert.equal(result.effect,undefined);
  }
  assert.throws(()=>taxEffect({...effect,year:2025}));
  assert.throws(()=>taxEffect({...effect,reimbursements:2001}));
});
test('a deduction exceeding taxable income is not presented as a loss-carryforward decision',()=>{
  const r=taxEffect({...effect,kind:'additional',income:10000,candidate:20000});
  assert.equal(r.effect,0);assert.equal(r.appliedDeduction,10000);assert.equal(r.unusedDeduction,10000);
});
const donation={year:2026,paid:12000,refunded:1000,incomeBase:50000,alreadyUsed:2000,eligible:'yes',receipt:'yes'};
test('ordinary donations respect other donations, the 20% income base and refunds',()=>{
  const r=donationCheck(donation);assert.equal(r.net,11000);assert.equal(r.ceiling,10000);assert.equal(r.candidate,8000);assert.equal(r.reviewCarryforward,3000);
  assert.equal(donationCheck({...donation,alreadyUsed:12000}).candidate,0);
});
test('missing donation evidence is unassessed, not a zero-eligibility verdict',()=>{
  const r=donationCheck({...donation,receipt:'no'});assert.equal(r.supported,false);assert.equal(r.candidate,undefined);
  assert.throws(()=>donationCheck({...donation,refunded:13000}));
});
const care={year:2026,paid:7000,excluded:500,reimbursed:500,qualifies:'yes',bank:'yes',invoice:'yes',location:'germany'};
test('childcare uses net eligible costs and one combined per-child cap',()=>{
  assert.equal(childcareCheck(care).candidate,4800);
  assert.equal(childcareCheck({...care,paid:3500}).candidate,2000);
  assert.equal(childcareCheck({...care,paid:0,excluded:0,reimbursed:0}).candidate,0);
});
test('cash, missing evidence and foreign-child cases stop the childcare numerical model',()=>{
  for(const change of [{bank:'no'},{invoice:''},{qualifies:'no'},{location:'abroad'}]) assert.equal(childcareCheck({...care,...change}).supported,false);
  assert.throws(()=>childcareCheck({...care,reimbursed:7000}));
});
test('insurance review never turns personal spending or prefilled data into an extra deduction',()=>{
  const r=insuranceCheck({year:2026,kind:'basic',paid:4800,refunded:200,certificate:'yes',prefilled:'yes'});
  assert.equal(r.netPaid,4600);assert.equal(r.candidate,null);assert.equal(r.duplicate,true);assert.match(r.status,/Reconcile/);
});
const residence={year:2026,person:'citizen',purpose:'general',days:180,prior4:500,prior7:800,nrYears:1,highIncome:'no',liableElsewhere:'yes'};
test('returnee may meet the 60+365 rule below 182 days, and history distinguishes RNOR',()=>{
  assert.match(indianResidency(residence).status,/ordinarily resident screening/);
  assert.match(indianResidency({...residence,days:182,prior4:400,prior7:700}).status,/RNOR/);
  assert.match(indianResidency({...residence,days:59}).status,/Non-resident/);
  assert.equal(indianResidency({...residence,prior4:''}).status,'Needs review');
  assert.match(indianResidency({...residence,days:182,nrYears:''}).status,/NOR review/);
});
test('visiting citizen income threshold and 120-day boundary are screened separately',()=>{
  assert.match(indianResidency({...residence,purpose:'visit',highIncome:'yes',days:120}).status,/RNOR/);
  assert.match(indianResidency({...residence,purpose:'visit',highIncome:'yes',days:119}).status,/Non-resident/);
  assert.match(indianResidency({...residence,purpose:'visit',highIncome:'no',days:120}).status,/Non-resident/);
  assert.equal(indianResidency({...residence,purpose:'visit',highIncome:''}).status,'Needs review');
});
test('deemed residence is checked after ordinary residence, never replacing an ROR case',()=>{
  assert.match(indianResidency({...residence,days:20,highIncome:'yes',liableElsewhere:'no'}).status,/RNOR/);
  assert.equal(indianResidency({...residence,days:20,highIncome:'yes',liableElsewhere:''}).status,'Needs review');
  assert.match(indianResidency({...residence,highIncome:'yes',liableElsewhere:'no'}).status,/ordinarily resident screening/);
});
test('overseas employment, PIO distinctions and old/new Indian law are preserved',()=>{
  assert.match(indianResidency({...residence,purpose:'leaving'}).status,/Non-resident/);
  assert.match(indianResidency({...residence,person:'pio',purpose:'leaving'}).status,/ordinarily resident screening/);
  assert.match(indianResidency({...residence,year:2025}).law,/1961/);
  assert.match(indianResidency(residence).law,/2025/);
  assert.throws(()=>indianResidency({...residence,prior7:400}));
  assert.throws(()=>indianResidency({...residence,days:366}));
});
test('transfer quote uses the same total debit, subtracts EUR fee before FX and INR fee after',()=>{
  const a=transferQuote(1000,{feeEUR:5,rate:90,feeINR:100});assert.equal(a.received,89450);
  const b=transferQuote(1000,{feeEUR:0,rate:89,feeINR:0});assert.equal(b.received,89000);
  assert.equal(a.received-b.received,450);
  assert.throws(()=>transferQuote(1000,{feeEUR:1001,rate:90,feeINR:0}));
  assert.throws(()=>transferQuote(1000,{feeEUR:0,rate:0,feeINR:0}));
});
const fd=input=>{const form=new FormData();for(const [key,value]of Object.entries(input))form.set(key,String(value));return form;};
test('commuting year references keep one-way distance and home working distinct',()=>{
  const base={category:'Commuting',distance:30,officeDays:150,homeDays:0,transportMode:'car'};
  assert.equal(calculateExpenseCore(fd({...base,year:2026})).estimated,1710);
  assert.equal(calculateExpenseCore(fd({...base,year:2025})).estimated,1470);
  assert.equal(calculateExpenseCore(fd({...base,year:2024})).estimated,1470);
  assert.equal(calculateExpenseCore(fd({...base,year:2026,homeDays:60})).estimated,2070);
  assert.equal(calculateExpenseCore(fd({category:'Home office',year:2026,homeDays:250})).estimated,1260);
});
test('public transport alternatives are not added to distance allowance, and taxis remain spending',()=>{
  const r=calculateExpenseCore(fd({category:'Commuting',year:2026,distance:100,officeDays:200,transportMode:'public',publicCost:5000,taxiCost:100,reimbursement:500}));
  assert.equal(r.estimated,5000);assert.equal(r.actual,5100);assert.match(r.warning,/NOT been deducted/);
  assert.throws(()=>calculateExpenseCore(fd({category:'Commuting',year:2026,officeDays:300,homeDays:66})));
  assert.throws(()=>calculateExpenseCore(fd({category:'Commuting',year:2026,distance:-10})));
});
test('equipment share is a candidate and general spending remains unassessed',()=>{
  const r=calculateExpenseCore(fd({category:'Work equipment',year:2026,amount:400,workShare:80}));assert.equal(r.actual,400);assert.equal(r.estimated,320);assert.match(r.warning,/depreciation/);
  assert.equal(calculateExpenseCore(fd({category:'Insurance',year:2026,quantity:12,amount:100})).estimated,null);
});
test('2026 GKV cap and employee shares match independently worked premium examples',()=>{
  assert.equal(employeeHealthAnnual(60000,2.69),5187);
  assert.ok(Math.abs(employeeHealthAnnual(80000,2.69)-6029.8875)<1e-8);
  assert.ok(Math.abs(employeeHealthAnnual(80000,3.29)-6239.1375)<1e-8);
  assert.equal(employeeHealthAnnual(100000,0),5091.75);
});
test('2026 employee payroll social contributions respect separate caps and Saxony',()=>{
  const r=taxClassSocial2026(48000,'Hesse (Hessen)',2.9,'none');
  assert.deepEqual([r.pension,r.unemployment,r.health,r.care],[4464,624,4200,1152]);
  const cap=taxClassSocial2026(200000,'Saxony (Sachsen)',2.9,'one');
  assert.equal(cap.pension,9430.2);assert.equal(cap.unemployment,1318.2);assert.ok(Math.abs(cap.care-1604.25)<1e-8);
});
test('double-household sample separates housing cap from actual land journeys',()=>{
  assert.deepEqual(doubleHouseholdCandidate(550,10,30,150),{housing:5500,homeTrips:1710,combined:7210});
  assert.equal(doubleHouseholdCandidate(1500,12,0,0).housing,12000);
  assert.throws(()=>doubleHouseholdCandidate(550,13,30,150));
});
test('investment examples match a separately evaluated closed-form annuity',()=>{
  assert.equal(investmentProjection(1200,100,1,0).value,2400);
  assert.ok(Math.abs(investmentProjection(1000,0,1,12).value-1126.8250301319697)<1e-8);
  assert.ok(Math.abs(investmentProjection(0,100,1,12).value-1268.250301319697)<1e-8);
  assert.ok(Math.abs(investmentProjection(1000,0,1,-12).value-886.3848717161292)<1e-8);
  assert.throws(()=>investmentProjection(1000,100,1.5,5));
});
const records=[{year:2026,category:'Work equipment',paymentDate:'2026-06-01',actual:400,estimated:320,receiptRef:' =HYPERLINK("x")',note:'private "note"',basis:{workShare:'80'}},{year:2025,category:'Commuting',actual:0,estimated:1470},{category:'Old record',amount:100}];
test('adviser exports isolate years, flag old records and neutralize spreadsheet formulas',()=>{
  const csv=taxRecordsCSV(records,2026);assert.match(csv,/400/);assert.doesNotMatch(csv,/1470/);assert.match(csv,/' =HYPERLINK/);assert.match(csv,/private ""note""/);
  assert.equal(recordsForYear(records,2026).unassigned.length,1);
  const text=adviserText({expenses:records,taxEvidence:{'2026:receipts':true}},2026);
  assert.match(text,/\[x\] Match each expense/);assert.match(text,/Records without a year: 1/);assert.match(text,/workShare/);assert.doesNotMatch(text,/1470/);
});
test('finder preserves explicit negative/unknown answers and prioritises potential topics',()=>{
  const result=opportunityResults({employment:'employee',work:'hybrid',parents:'no',donated:'yes'});
  assert.equal(result.find(r=>r.id==='parents').status,'Not indicated by your answers');
  assert.equal(result.find(r=>r.id==='insurance').status,'Needs review');
  assert.equal(result[0].status,'Potentially relevant');assert.equal(new Set(result.map(r=>r.id)).size,result.length);
});
test('rendered pack escapes imported text and all preparation sections render without a browser',()=>{
  const title=()=>'<h1>Tax preparation</h1>';
  const html=taxPlanningPage('export',{expenses:[{year:2026,category:'<img src=x onerror=alert(1)>',actual:1}]},{title});
  assert.doesNotMatch(html,/<img/);assert.match(html,/&lt;img/);
  for(const part of ['finder','checks','donations','childcare','cases','student','partyear','cross','effect'])assert.match(taxPlanningPage(part,{}, {title}),/id="taxPlanning"/);
});
